Clase Rectangulo
    Privado Definir base Como Entero;
    Privado Definir altura Como Entero;

    Metodo Constructor(unaBase Como Entero, unaAltura Como Entero)
        Este.base <- unaBase;
        Este.altura <- unaAltura;
    FinMetodo

    Publico Metodo Area() Como Entero
        Retornar Este.base * Este.altura;
    FinMetodo
FinClase

Proceso CalcularArea
    Definir base Como Entero;
    Definir altura Como Entero;
    Definir rectangulo Como Rectangulo;
    Leer base;
    Leer altura;
    rectangulo <- Nuevo Rectangulo(base, altura);
    Escribir rectangulo.Area();
FinProceso
